// std::vector::insert(pos, elem) Implementation Details

const size_t idx = pos - data_;

if (size_ == cap_) {
    // Case A: Reallocation Path
    T* new_data = internal_allocate(cap_ * 2);

    // 1. Move elements before pos
    std::uninitialized_move(data_, pos, new_data);
    // 2. Construct new element
    construct(new_data + idx, elem);
    // 3. Move elements after pos
    std::uninitialized_move(pos, data_ + size_, new_data + idx + 1);

    data_ = new_data; // Update buffer pointer
} else {
    // Case B: In-Place Shift Path
    // Shift elements [pos, end) one step right
    std::move_backward(pos, data_ + size_, data_ + size_ + 1);

    // Insert element
    *pos = elem;
}
size_++;
return data_ + idx;
